    section: "A", questionRef: "2021 HL Q4(b)(ii)",
    questionText: "Identify and explain the microstructure which is present at 0.83% carbon steel, up to 723°C.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 4,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The microstructure present at 0.83% carbon content, up to 723°C, is called pearlite.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Pearlite is a layered structure with alternate layers of ferrite and cementite.", marks: null },
    { id: "r-3", kind: "point", verbatim: "It has a “mother of pearl” sheen when fractured.", marks: null },
    ],
