    section: "A", questionRef: "2021 HL Q5(a)(ii)",
    questionText: "Explain why crystal structure B is likely to be more ductile than crystal structure A.",
    tariffModel: {"kind":"fixed"}, totalMarks: 6,
    rows: [
    { id: "r-1", kind: "point", verbatim: "The face-centered cubic unit cell has atoms at each of the eight corners of a cube, plus one atom in the centre of each of the cubes faces giving a total of 14 atoms while the body- centered cubic unit cell has atoms at each of the eight corners of a cube, plus one atom in the centre of the cube giving a total of 9 atoms. The more atoms in the structure the more ductile the material is as the atoms slip across each other easier.", marks: 6 },
    ],
