    paperFileid: "LC027ALP000EV",
    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2021 Higher Level — © State Examinations Commission.",
    id: "eng-2021-hl-q9-b-iii", topicId: "eng-2-15", conceptId: "aid-diagram-operation-idler-gear",
    section: "A", questionRef: "2021 HL Q9(b)(iii)",
    questionText: "Describe, with the aid of a diagram, the operation of an idler gear.",
