    questionText: "Differentiate between pyrometallurgy and hydrometallurgy.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 5,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Pyrometallurgy is a high-temperature process that involves the heating of ores to extract metals. This process typically involves the use of heat and chemical reactions in a furnace or smelter.", marks: null },
    { id: "r-2", kind: "point", verbatim: "Hydrometallurgy is a process that uses aqueous solutions to extract metals from ores. It involves dissolving the metal compounds in water or acid solutions and then separating and purifying the metal from the solution.", marks: null },
    ],
