    section: "A", questionRef: "2025 HL Q2(a)(ii)",
    questionText: "Describe two advantages of using hydrogen as a fuel source.",
    tariffModel: {"kind":"orderedSplit","notation":"3 + 2"}, totalMarks: 5,
