    questionText: "Describe, with the aid of a diagram(s), the precision surface grinding process.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Precision surface grinding is a metal cutting process in which flat and extremely smooth surfaces are produced.", marks: null },
    { id: "r-2", kind: "point", verbatim: "The grinding wheel rotates and the workpiece, usually held in a magnetic chuck, is fed to and from continuously.", marks: null },
    { id: "r-3", kind: "point", verbatim: "At the end of each stroke, the table is moved across the wheel by a small amount. The grinding wheel can be lowered to take a new cut.", marks: null },
    ],
