    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2026 Higher Level — © State Examinations Commission.",
    id: "eng-2026-hl-q1-k", topicId: "eng-1-3", conceptId: "briefly-why-metals-face-centred-cubic",
    section: "A", questionRef: "2026 HL Q1(k)",
    stem: "Give brief answers to any ten of the following:",
    questionText: "Explain briefly why metals with a face centred cubic (FCC) structure tend to be more ductile than metals with a body centred cubic (BCC) structure.",
    tariffModel: {"kind":"fixed"}, totalMarks: 5,
    rows: [
    { id: "r-1", kind: "point", verbatim: "FCC structure has a greater atom density than BCC. This allows metals to glide across each other without breaking bonds. This close pack structure makes FCC metals more ductile.", marks: 5 },
    ],
