    id: "eng-2026-hl-q3-a-iii", topicId: "eng-2-15", conceptId: "how-torsional-forces-may-affect-lifespan",
    section: "A", questionRef: "2026 HL Q3(a)(iii)",
    questionText: "Explain how torsional forces may affect the lifespan of the crankshaft.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 4,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Torsional forces are twisting forces that act along the axis of the crankshaft.", marks: null },
    { id: "r-2", kind: "point", verbatim: "These forces occur during engine operation as the crankshaft rotates and transmits power.", marks: null },
    { id: "r-3", kind: "point", verbatim: "Repeated twisting can cause fatigue, leading to cracks or failure over time. It may also cause deformation, impact on engine performance and increase wear at stress points.", marks: null },
    ],
