    id: "eng-2026-hl-q5-a-i", topicId: "eng-1-5", conceptId: "reasons-why-bronze-suitable-manufacture-ship",
    section: "A", questionRef: "2026 HL Q5(a)(i)",
    questionText: "Outline two reasons why bronze is suitable for the manufacture of the ship’s propeller.",
    tariffModel: {"kind":"fixed"}, totalMarks: 4,
