    schemeCitation: "Marking points quoted from the SEC marking scheme, Engineering 2026 Higher Level — © State Examinations Commission.",
    id: "eng-2026-hl-q5-a-iii", topicId: "eng-3-7", conceptId: "why-regular-inspection-or-replacement-anodes",
    section: "A", questionRef: "2026 HL Q5(a)(iii)",
    questionText: "Explain why regular inspection or replacement of the anodes is necessary in marine environments.",
