    id: "eng-2026-hl-q6-a-i", topicId: "eng-1-5", conceptId: "reasons-why-tubular-aluminium-suitable-manufacture",
    section: "A", questionRef: "2026 HL Q6(a)(i)",
    questionText: "Outline two reasons why tubular aluminium is suitable for the manufacture of the lighting truss shown.",
    tariffModel: {"kind":"fixed"}, totalMarks: 4,
